import {DEFAULT_POLICY,now,cents,totals,balance,accountAt,obligationBalance,policyAt,report,annualReport,monthEnd,allocationAdvice,productReport,ms,transactionAccountSlots,transactionAccountIssue,validateTransactionTime,cashCorrectionIssue} from '/core.mjs';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
let state=null,csrf=null,authState=null,page=location.hash.slice(1)||'overview',tab='monthly',txFilter='all',accountFilter='all',month=now().slice(0,7),year=now().slice(0,4),trendPeriod='month',busy=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null?'—':(v<0?'−':'')+'¥'+(Math.abs(v)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const num=v=>v==null?'—':(v/100).toFixed(2);
const date=v=>v?v.slice(0,10).replaceAll('-','.'):'未核验';
const stamp=v=>v.endsWith('+08:00')?v:(v.length===16?v+':00':v)+'+08:00';
const localNow=()=>now().slice(0,23);
const titleMap={overview:'财政总览',accounts:'账户与余额',events:'财政事项',reports:'财政报告',settings:'政策与设置'};
const paths={overview:'overview',accounts:'wallet',events:'arrows',reports:'chart',settings:'settings'};
const icon=(name,size=18)=>{const shapes={overview:'<rect x="3" y="3" width="7" height="7" rx="1.3"/><rect x="14" y="3" width="7" height="7" rx="1.3"/><rect x="3" y="14" width="7" height="7" rx="1.3"/><rect x="14" y="14" width="7" height="7" rx="1.3"/>',wallet:'<path d="M20 8H5a2 2 0 0 1 0-4h13v4M4 8v11a1 1 0 0 0 1 1h15V8M20 12h-5v4h5"/>',arrows:'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',leaf:'<path d="M19 4C9 3 3 8 5 15c8 4 15-2 14-11ZM4 21l11-12"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>',empty:'<path d="M3 8h18v13H3zM7 8V4h10v4M8 13h8"/>',chevron:'<path d="m9 5 7 7-7 7"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.wallet}</svg>`;};
const btn=(label,action,primary=false,ic='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${ic?icon(ic,15):''}${label}</button>`;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4000);}
async function api(path,{method='GET',body,raw=false}={}){let res;try{res=await fetch('/api'+path,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(csrf?{'X-CSRF-Token':csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});}catch{throw new Error('连接中断，数据尚未保存。请联网后重试。');}if(!res.ok){let e;try{e=await res.json();}catch{}if(res.status===401){state=null;csrf=null;await boot();}throw new Error(e?.error||'请求未完成，请重试');}return raw?res:res.json();}
async function command(type,payload){const pending={expectedRevision:state.revision,requestId:crypto.randomUUID(),command:{type,payload}};try{state=await api('/command',{method:'POST',body:pending});}catch(e){try{state=await api('/state');}catch{}throw e;}render();}
async function boot(){try{authState=await api('/session');csrf=authState.csrf;if(!authState.authenticated)return renderAuth();state=await api('/state');render();}catch(e){app.innerHTML=`<div class="setup-panel panel"><h2>账本暂时无法打开</h2><p>${esc(e.message)}</p>${btn('重新连接','reload',true,'refresh')}</div>`;}}
function renderAuth(){const setup=!authState.configured;app.innerHTML=`<div class="auth"><section class="auth-art"><a class="brand" href="#"><img src="/icon.svg" alt=""><div><strong>Personal<br>Treasury</strong><small>个人财政管理</small></div></a><div class="auth-quote"><div class="eyebrow">A quieter way to manage money</div><h1>把每一份积累，<br>留给更远的未来。</h1><p>少记账，重核算。<br>让真实的余额，成为长期规划的起点。</p></div><div class="auth-copy">PERSONAL TREASURY · EST. 2026</div></section><section class="auth-form-wrap"><form class="auth-form" data-form="auth"><div class="eyebrow">YOUR PRIVATE TREASURY</div><h2>${setup?'建立你的私人账本':'欢迎回来'}</h2><p>${setup?'设置独立密码，保护你的资产与财政记录。':'登录后继续查看你的财政状况与长期积累。'}</p>${setup&&authState.setupTokenRequired?field('初始设置码','setupToken','password','','由部署时设置'):''}${field('登录密码','password','password','',setup?'至少12位，建议使用独立长密码':'输入你的账本密码',true)}${setup?field('再次输入密码','confirmPassword','password','',undefined,true):''}<div class="form-error"></div><button class="btn primary" type="submit">${setup?'创建私人账本':'解锁账本'} ${icon('arrow',15)}</button><p class="footnote">${icon('lock',12)} 独立登录 · 安全会话 · 不连接支付账户</p></form></section></div>`;}
const field=(label,name,type='text',value='',help='',required=false)=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="0.01" min="0"':type==='datetime-local'?'step="0.001"':''} ${type==='password'?`autocomplete="${name==='password'&&!authState?.configured?'new-password':'current-password'}"`:''}>${help?`<span class="form-help">${esc(help)}</span>`:''}</label>`;
const select=(label,name,items,value)=>`<label class="field">${esc(label)}<select name="${name}" required>${items.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
function nav(bottom=false){return `<nav class="${bottom?'bottom-nav':'nav'}" aria-label="主要导航">${Object.entries(titleMap).map(([key,label])=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(paths[key])}<span>${bottom?({'overview':'总览',accounts:'账户',events:'事项',reports:'报告',settings:'设置'}[key]):label}</span></a>`).join('')}</nav>`;}
function shell(content){return `<div class="layout"><aside class="sidebar"><a class="brand" href="#overview"><img src="/icon.svg" alt=""><div><strong>Personal<br>Treasury</strong><small>个人财政管理</small></div></a><p class="nav-label">MY TREASURY</p>${nav()}<div class="sidebar-foot"><strong>${icon('leaf',13)} 少记账，重核算</strong><p>记录真实事项<br>看清长期积累</p><div class="version">V1.0 · PRIVATE LEDGER</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">个人财政 <span>/</span> <strong>${titleMap[page]}</strong></div><a href="#overview" class="mobile-brand"><img src="/icon.svg" alt="">Personal Treasury</a><div class="top-actions"><time>${now().slice(0,10).replaceAll('-',' / ')}</time><button class="btn ghost small" data-action="reload" aria-label="刷新账本">${icon('refresh',15)}</button><div class="avatar" title="私人账本">PT</div></div></header><main class="main">${content}</main></div>${nav(true)}</div>`;}
function head(title,subtitle,actions='',en='MY PERSONAL TREASURY'){return `<div class="page-head ${page==='reports'?'report-head':''}"><div><p class="eyebrow">${en}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function render(){if(!state)return;page=titleMap[page]?page:'overview';let content;if(!state.setup)content=initialView();else content=({overview:overviewView,accounts:accountsView,events:eventsView,reports:reportsView,settings:settingsView}[page])();app.innerHTML=shell(content);document.querySelectorAll('[data-progress]').forEach(x=>x.style.setProperty('--progress',Number(x.dataset.progress)+'%'));}
function initialView(){return head('让财政状况，从此清晰','先确认一个起点，系统会记住此后的每一步。','','GETTING STARTED')+`<section class="panel setup-panel"><div class="banner-icon">${icon('leaf',24)}</div><h2>从真实的资产余额开始</h2><p>不必补录过去的每一笔交易。选定建账时点，再录入当时的账户余额、理财估值和未结清的债权债务。</p><form data-form="initialize">${field('首次建账时点（北京时间）','at','datetime-local',now().slice(0,10)+'T00:00','起点余额应当对应这一时点。早于起点的事项不再重复登记。',true)}<div class="notice">初始政策：储蓄基准 ¥15,000；流动留存 ¥300；自筹收入10%储蓄。之后可在设置中查看和调整。</div><div class="form-error"></div><div class="actions"><button class="btn primary" type="submit">开始首次建账 ${icon('arrow',15)}</button>${btn('从备份恢复','restore')}</div></form><div class="setup-step"><span class="step-num">1</span><div class="step-text"><h3>录入账户与期初余额</h3><p>流动、储蓄分别归组；每只理财产品独立录入。</p></div></div><div class="setup-step"><span class="step-num">2</span><div class="step-text"><h3>登记尚未结清的借还款</h3><p>借出的钱仍是债权，不直接减少净资产。</p></div></div><div class="setup-step"><span class="step-num">3</span><div class="step-text"><h3>平日少记录，月末统一核算</h3><p>记录收入和特殊事项，普通消费由余额变化推算。</p></div></div></section>`;}
function metric(label,value,note,kind=''){return `<div class="panel metric"><div class="metric-label">${label}${icon(kind||'wallet',14)}</div><div class="metric-value">${value}</div><small>${note}</small></div>`;}
function simpleChart(records,key='net'){if(!records.length)return '<div class="chart-empty">封存首个月报后，长期趋势将出现在这里</div>';const vals=records.map(x=>key==='net'?x.report.closing.net:x.report.surplus);const min=Math.min(...vals)*.95,max=Math.max(...vals)*1.05,range=max-min||100;const x=i=>38+i*(440/Math.max(1,vals.length-1)),y=v=>145-((v-min)/range)*110;const pts=vals.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<svg class="line-chart" viewBox="0 0 510 180" role="img" aria-label="${key==='net'?'净资产':'财政结余'}月度趋势">${[35,85,135].map(y=>`<line class="chart-grid" x1="25" y1="${y}" x2="490" y2="${y}"/>`).join('')}<polyline class="chart-line" points="${pts}"/>${vals.map((v,i)=>`<circle class="chart-point" cx="${x(i)}" cy="${y(v)}" r="3"><title>${records[i].month}：${money(v)}</title></circle><text class="chart-axis" text-anchor="middle" x="${x(i)}" y="170">${i%Math.max(1,Math.ceil(records.length/6))===0?(records[i].month.length===4?records[i].month+'年':records[i].month.slice(5)+'月'):''}</text>`).join('')}</svg>`;}
function latestReports(){const map=new Map();for(const r of state.settlements)map.set(r.month,r);return [...map.values()].sort((a,b)=>a.month.localeCompare(b.month));}
function overviewView(){const t=totals(state),p=policyAt(state,now());let r;try{r=report(state,now().slice(0,7));}catch{}const ratio=Math.max(0,Math.round(t.savings/p.reserve*100))||0;const accounts=state.accounts.filter(a=>accountAt(a,now())?.status==='active');const stale=accounts.filter(a=>balance(state,a.id).estimated);const records=latestReports();const recent=state.transactions.filter(t=>!t.void).sort((a,b)=>ms(b.at)-ms(a.at)).slice(0,4);
return head('财政总览','看清当下，让积累有迹可循。',btn('核验余额','balances',false,'refresh')+btn('记录事项','tx',true,'plus'))+
(!accounts.length?`<div class="notice"><span>建账起点已确认。接下来逐一添加实际账户，填写期初余额。</span>${btn('添加首个账户','account-add',true,'plus')}</div>`:'')+
`<div class="hero-grid"><section class="panel net-card"><div class="label">当前净资产 ${icon('lock',13)}</div><div class="net-value"><span class="currency">¥</span>${(t.net/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}</div><small>全部账户资产与应收债权，减去应付债务</small><div class="net-bottom"><span>总资产 <strong>${money(t.assets)}</strong></span><span>应付债务 <strong>${money(t.liabilities)}</strong></span></div></section><section class="panel reserve-card"><div class="reserve-top"><h2>储蓄保障率</h2><span class="badge ${ratio<100?'warn':''}">${ratio>=100?'已达储备基准':'积累进行中'}</span></div><div><div class="reserve-number">${ratio}%<span>/ 基准 ${money(p.reserve)}</span></div><div class="progress" data-progress="${Math.min(ratio,100)}"><i></i></div><div class="reserve-detail"><span>储蓄 ${money(t.savings)}</span><span>${t.savings<p.reserve?'距基准 '+money(p.reserve-t.savings):'超出 '+money(t.savings-p.reserve)}</span></div></div></section></div><div class="metrics">${metric('本月普通收入',money(r?.income??0),'已登记的外部收入','arrows')}${metric('本月财政结余',money(r?.surplus),'余额差额暂估 · 待月末核验','chart')}${metric('流动账户资金',money(t.liquid),'自由调配 '+money(t.freeLiquid),'wallet')}${metric('本月投资损益',money(r?.investmentGain),'估值暂算 · 不并入普通结余','leaf')}</div>`+
(stale.length?`<div class="notice"><span>${icon('refresh',13)} ${stale.length}个账户为暂估余额或超过24小时未核验，月报以期末确认值为准。</span><button class="btn small" data-action="balances">更新余额</button></div>`:'')+
(t.freeLiquid<p.freeLow&&accounts.length?`<div class="notice warn"><span>自由调配资金偏低（${money(t.freeLiquid)}）。${t.liquid<p.low?'流动账户组也低于政策预警线。':'流动账户组共'+money(t.liquid)+'，尚未触发'+money(p.low)+'政策线。'}</span></div>`:'')+
`<div class="two-col"><section class="panel"><div class="panel-head"><h2>账户分布</h2><a class="btn ghost small" href="#accounts">管理账户 ${icon('chevron',12)}</a></div><div class="group-bar" data-progress="${t.liquid+t.savings?Math.max(0,Math.min(100,t.savings/(t.liquid+t.savings)*100)):0}"><i></i><b></b></div><div class="legend"><span>● 储蓄资金 <strong>${money(t.savings)}</strong></span><span>● 流动资金 <strong>${money(t.liquid)}</strong></span></div>${accounts.slice(0,4).map(a=>accountRow(a)).join('')||empty('账户等待录入','每个实际账户只计入一次资产。')}</section><section class="panel"><div class="panel-head"><h2>长期净资产</h2><span class="badge">已封存月份</span></div>${simpleChart(records.slice(-6))}<div class="footnote">${records.length?'基于正式月报；已过时的报表需修订后用于比较。':'积累不必一蹴而就。从第一个月开始，留下可追溯的财政记录。'}</div></section></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>最近财政事项</h2><a href="#events" class="btn ghost small">全部记录 ${icon('chevron',12)}</a></div>${recent.map(t=>txRow(t)).join('')||empty('还没有财政事项','只记录收入与必要的资金变化。')}</section><section class="panel"><div class="panel-head"><h2>储蓄资金可用性</h2>${icon('leaf',17)}</div><div class="key-value"><span>可以立即自由使用</span><strong>${money(t.freeSavings)}</strong></div><div class="key-value"><span>需要赎回才能使用</span><strong>${money(t.redeemSavings)}</strong></div><div class="key-value"><span>其他限定用途</span><strong>${money(t.savings-t.freeSavings-t.redeemSavings)}</strong></div><p class="footnote">储蓄基准按全部储蓄资产计算，可用性单独展示。债权不计入储蓄账户组。</p></section></div>`;}
function empty(title,detail){return `<div class="empty">${icon('empty',28)}<h3>${title}</h3><p>${detail}</p></div>`;}
function accountRow(a){const b=balance(state,a.id),h=accountAt(a,now());return `<div class="account-row"><div class="account-icon">${esc(a.platform.slice(0,1))}</div><div class="account-info"><strong>${esc(a.name)}</strong><small>${h.group==='liquid'?'流动':'储蓄'} · ${esc(a.platform)} · ${date(b.asOf)}</small></div><div class="amount">${money(b.amount)}</div></div>`;}
const kindNames={income:'收入',expense:'特殊支出',transfer:'内部调拨',lend:'借出本金',repay_receivable:'收回本金',borrow:'借入本金',repay_debt:'归还借款',invest:'申购理财',redeem:'赎回理财',dividend:'现金分红',adjustment:'净资产特殊调整',writeoff:'债权核销'};
const categoryNames={family:'家庭常规生活费',labor:'自筹劳动收入',supplement:'家庭临时补充',other:'其他外部收入'};
const accName=id=>state.accounts.find(a=>a.id===id)?.name||'—';
function txRow(t,actions=false){return `<div class="account-row"><div class="account-icon">${icon(t.kind==='income'?'plus':'arrows',15)}</div><div class="account-info"><strong>${esc(t.memo)} ${t.void?'<span class="badge red">已作废</span>':''}</strong><small>${date(t.at)} · ${kindNames[t.kind]}${t.kind==='income'?' / '+categoryNames[t.category]:''}${t.version>1?' · v'+t.version:''}</small></div><span class="amount ${['income','dividend'].includes(t.kind)?'positive':''}">${money(t.amount)}</span>${actions?`<button class="btn small" data-action="tx-edit" data-id="${t.id}">查看 / 更正</button>`:''}</div>`;}
function accountsView(){const t=totals(state),list=state.accounts.filter(a=>accountFilter==='all'||accountAt(a,now())?.group===accountFilter);const refs=state.setup.platformReferences||[];return head('账户与余额','每一个真实账户，只有一份资产。',btn('核验余额','balances',false,'refresh')+btn('新增账户','account-add',true,'plus'),'ACCOUNTS & BALANCES')+`<div class="metrics">${metric('流动资金合计',money(t.liquid),'含饭卡、交通卡等预付余额')}${metric('储蓄资金合计',money(t.savings),'含各类理财产品')}${metric('理财资产总值',money(t.investment),'产品估值独立核算')}${metric('应收债权',money(t.receivables),'独立于储蓄账户组')}</div><div class="tabs">${[['all','全部账户'],['liquid','流动账户'],['savings','储蓄账户']].map(([k,v])=>`<button data-action="account-filter" data-value="${k}" class="${accountFilter===k?'active':''}">${v}</button>`).join('')}</div><section class="panel"><div class="panel-head"><h2>实际账户 <small> / ${list.length}</small></h2><span class="badge">CNY · 人民币</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>账户 / 平台</th><th>财政归属</th><th>核验时点 / 状态</th><th class="right">余额</th><th></th></tr></thead><tbody>${list.map(a=>{const h=accountAt(a,now()),b=balance(state,a.id);return `<tr><td><span class="table-name">${esc(a.name)}</span><span class="table-sub">${esc(a.platform)} · ${{cash:'现金',prepaid:'预付储值',investment:'理财产品',transit:'在途资产'}[a.kind]}</span></td><td><span class="badge">${h.group==='savings'?'储蓄':'流动'}</span><span class="table-sub">${{free:'自由使用',restricted:'限定用途',redeem:'需要赎回'}[h.restriction]}</span></td><td>${date(b.asOf)}<span class="table-sub">${{active:'正常',inactive:'停用',archived:'归档'}[h.status]}${b.estimated?' · 暂估':''}</span></td><td class="right number">${money(b.amount)}</td><td class="right"><button class="btn small" data-action="account-edit" data-id="${a.id}">管理</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('还没有账户','点击“新增账户”，从微信、饭卡或银行卡开始。')}<p class="footnote">账户归档后历史保留；停用或归档前需核验为零余额。在途转账请先转入独立“在途资产”账户，到账后再转出。</p></section><h2 class="section-title">平台合计核对</h2><section class="panel"><div class="panel-head"><h2>按平台自动汇总</h2>${btn('录入平台参考值','platform-ref')}</div>${[...new Set(state.accounts.map(a=>a.platform))].map(p=>{const total=state.accounts.filter(a=>a.platform===p).reduce((n,a)=>n+balance(state,a.id).amount,0),ref=refs.filter(x=>x.platform===p).at(-1);return `<div class="key-value"><span>${esc(p)} ${ref?`<small>参考值 ${money(ref.amount)} · ${date(ref.asOf)}</small>`:''}</span><strong>${money(total)}</strong></div>`;}).join('')||'<p class="muted">账户建立后自动计算。</p>'}<p class="footnote">平台参考总资产仅用于核对，不加入总账；子账户只汇总一次。不同核验时点的参考值不自动判定为错误。</p></section>`;}
function eventsView(){const ts=state.transactions.filter(t=>txFilter==='all'||txFilter==='debt'&&['lend','repay_receivable','borrow','repay_debt','writeoff'].includes(t.kind)||txFilter==='investment'&&['invest','redeem','dividend'].includes(t.kind)||t.kind===txFilter).sort((a,b)=>ms(b.at)-ms(a.at));return head('财政事项','记录真实发生的资金变化，让核算更轻松。',btn('新增债权 / 债务','obligation-add')+btn('记录事项','tx',true,'plus'),'FINANCIAL EVENTS')+`<div class="notice"><span>日常餐费、交通和流动消费无需逐笔登记。借款本金、调拨、理财申赎请按实际性质记录。</span></div><div class="tabs">${[['all','全部事项'],['income','收入'],['expense','特殊支出'],['transfer','内部调拨'],['debt','借还款'],['investment','理财资金']].map(([k,v])=>`<button data-action="tx-filter" data-value="${k}" class="${txFilter===k?'active':''}">${v}</button>`).join('')}</div><section class="panel">${ts.length?ts.map(t=>txRow(t,true)).join(''):empty('没有符合条件的事项','普通消费会在月末由余额差额推算。')}</section><h2 class="section-title">债权与债务</h2><section class="panel">${state.obligations.length?`<div class="table-wrap"><table><thead><tr><th>对方 / 说明</th><th>类型</th><th class="right">剩余本金</th><th class="right">状态</th><th></th></tr></thead><tbody>${state.obligations.map(o=>{const b=obligationBalance(state,o);return `<tr><td>${esc(o.party)}<span class="table-sub">${esc(o.memo)}</span></td><td>${o.kind==='receivable'?'应收债权':'应付债务'}</td><td class="right number">${money(b)}</td><td class="right"><span class="badge">${b===0?'已结清':'未结清'}</span></td><td><button class="btn small" data-action="obligation-edit" data-id="${o.id}">更正档案</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('目前没有借还款档案','首次建账前的未结清本金录入期初值，之后通过真实事项更新。')}</section>`;}
function reportsView(){return head('财政报告','按月核验，为长期变化留下可靠记录。',`<input aria-label="报告月份" type="month" class="month-picker" id="month-picker" value="${month}">`,'REPORTS & INSIGHTS')+`<div class="tabs">${[['monthly','月度核算'],['investments','理财分析'],['annual','年度报告'],['history','历史与趋势']].map(([k,v])=>`<button data-action="report-tab" data-value="${k}" class="${tab===k?'active':''}">${v}</button>`).join('')}</div>`+({monthly:monthlyView,investments:investmentView,annual:annualView,history:historyView}[tab])();}
function getReport(){try{return report(state,month);}catch{return null;}}
function monthlyView(){const r=getReport();if(!r)return `<section class="panel">${empty('该月早于建账时间','请选择建账当月或之后的月份。')}</section>`;const frozen=state.settlements.filter(x=>x.month===month).at(-1);const ended=ms(r.end)<ms(now());return `<div class="notice ${frozen?.stale?'warn':''}"><span>${frozen?`${month}月报已封存 · v${frozen.version}${frozen.stale?' · 后续更正影响本期，需修订月报':''}`:ended?'尚未封存，正在核对本月财政事项。':'本月尚未结束，以下为暂估核算。'}${r.incomplete?' 本期为建账后的不完整自然月。':''}</span><div class="actions">${r.unconfirmedOpening?.length?btn('补核期初余额','opening-balances'):''}${ended?btn('核验期末余额','month-balances'):''}</div></div><div class="metrics">${metric('普通财政收入',money(r.income),'劳动与家庭等外部收入')}${metric('普通消费',money(r.consumption),'由余额差额推算，待确认')}${metric('特殊费用',money(r.special),'已登记支出与债权核销')}${metric('财政结余',money(r.surplus),'收入 − 普通消费 − 特殊费用','chart')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>资产与负债核对</h2><span class="badge">期末值</span></div>${[['流动账户组',r.closing.liquid],['储蓄账户组',r.closing.savings],['应收债权',r.closing.receivables],['应付债务',r.closing.liabilities],['净资产',r.closing.net],['净资产较期初变化',r.closing.net-r.opening.net],['独立投资损益',r.investmentGain],['其他已确认资产变化',r.otherChange]].map(([l,v])=>`<div class="key-value"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>政策执行</h2><span class="badge">${date(r.policy.effective)}生效</span></div>${[['月末理论应转储蓄',r.expectedSweep],['实际完成调拨',r.actualSweep],['尚待完成',r.sweepRemaining],['超过理论目标',r.sweepExcess]].map(([l,v])=>`<div class="key-value"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}<p class="footnote">按月末调拨前流动余额计算，已完成的同月调拨会加回基数，不会反复生成新建议。建议不会直接改变账户余额。</p><div class="actions">${btn('登记实际调拨','sweep',false,'arrows')}</div><h3 class="section-title">收入分配待办</h3>${r.allocations.filter(a=>a.remaining!==0).map(a=>`<div class="key-value"><span>${esc(state.transactions.find(t=>t.id===a.incomeId)?.memo)}<small class="table-sub">${a.remaining>0?'流动 → 储蓄':'储蓄 → 流动'}</small></span><strong>${money(Math.abs(a.remaining))}</strong></div>`).join('')||'<p class="footnote">已登记收入的政策分配均已完成，或无需跨组调拨。</p>'}${r.investmentAllocations?.filter(a=>a.remaining>0).length?'<h3 class="section-title">理财收益归储蓄待办</h3>'+r.investmentAllocations.filter(a=>a.remaining>0).map(a=>'<div class="key-value"><span>'+esc(a.memo)+'</span><strong>'+money(a.remaining)+'</strong></div>').join(''):''}</section></div><section class="panel"><div class="panel-head"><h2>月末特殊事项核对</h2>${btn('补录事项','tx',false,'plus')}</div><p class="footnote">先确认借还款、在途转账、理财资金与非日常资产变化，再确认差额确为本月普通消费。负数或不合理的差额应先追查原因。</p>${r.warnings.map(w=>`<div class="notice warn">${esc(w)}</div>`).join('')}<div class="checks">${[['incomes','所有普通收入已登记'],['savings','储蓄动用、内部调拨和在途资产已核对'],['loans','债权债务、归还和必要特殊事项已核对'],['investments','理财估值、申购赎回和现金分红已核对'],['consumption',`确认${money(r.consumption)}为余额差额推算的普通消费`]].map(([k,v])=>`<label><input type="checkbox" name="close-${k}">${v}</label>`).join('')}</div><div class="actions"><button class="btn primary" data-action="close-month" ${!ended||!r.canClose?'disabled':''}>${frozen?'修订并封存 v'+(frozen.version+1):'确认并封存月报'} ${icon('check',14)}</button><small>${!ended?'自然月结束后方可正式封存':!r.canClose?'请完成逐账户期末核验，处理异常差额':'封存后保留正式版本；之后可更正并修订。'}</small></div></section><h2 class="section-title">储蓄资金动用明细</h2><section class="panel">${r.savingsUses.length?r.savingsUses.map(t=>txRow(t)).join(''):empty('本月未登记储蓄对外动用','借出本金、费用支出与内部调拨分别核算。')}</section><h2 class="section-title">各账户期初与期末</h2><section class="panel table-wrap"><table><thead><tr><th>实际账户</th><th class="right">期初余额</th><th class="right">期末余额</th><th class="right">变动</th></tr></thead><tbody>${state.accounts.filter(a=>ms(a.createdAt)<=ms(r.end)).map(a=>{const a0=balance(state,a.id,r.start)?.amount??0,a1=balance(state,a.id,r.end)?.amount??0;return `<tr><td>${esc(a.name)}</td><td class="right number">${money(a0)}</td><td class="right number">${money(a1)}</td><td class="right number">${money(a1-a0)}</td></tr>`;}).join('')}</tbody></table></section>`;}
function investmentView(){const r=getReport();if(!r)return empty('该月早于建账时间','请选择其他月份。');return `<div class="metrics">${metric('当月投资损益',money(r.investmentGain),'不参与劳动收入10% / 90%分配')}${metric('理财期末总价值',money(r.products.reduce((n,p)=>n+p.end,0)),'每只产品仅计入一次')}${metric('占储蓄资产比例',r.closing.savings?(r.products.reduce((n,p)=>n+p.end,0)/r.closing.savings*100).toFixed(1)+'%':'—','按当期储蓄账户组总额计算')}${metric('累计投资损益',money(state.accounts.filter(a=>a.kind==='investment'&&ms(a.createdAt)<=ms(r.end)).reduce((n,a)=>n+productReport(state,a,state.setup.at,r.end).gain,0)),'从建账时点累计')}</div><section class="panel"><div class="panel-head"><h2>每只产品，单独核算</h2>${btn('登记理财资金','investment-tx',true,'plus')}</div>${r.products.length?`<div class="table-wrap"><table><thead><tr><th>产品</th><th class="right">月初价值</th><th class="right">追加 / 赎回</th><th class="right">现金分红</th><th class="right">月末价值</th><th class="right">投资损益</th></tr></thead><tbody>${r.products.map(p=>`<tr><td>${esc(p.name)}<span class="table-sub">${esc(p.platform)}</span></td><td class="right number">${money(p.begin)}</td><td class="right number">${money(p.put)}<span class="table-sub">${money(p.take)}</span></td><td class="right number">${money(p.dividend)}</td><td class="right number">${money(p.end)}</td><td class="right number ${p.gain<0?'negative':'positive'}">${money(p.gain)}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有理财产品','在“账户与余额”中新增性质为理财产品的账户。')}<p class="footnote">投资损益 = 月末价值 − 月初价值 − 投入 + 取出 + 对外现金分红。申赎按实际价值登记，不把本金当收益。V1.0不推算精确收益率或不可靠的已实现 / 未实现拆分。</p></section>`;}
function annualView(){const r=annualReport(state,year);return `<div class="actions"><label for="year-picker" class="muted">报告年份</label><input id="year-picker" class="year-picker" type="number" min="2000" max="2200" value="${year}"></div><p class="footnote">仅汇总已封存的 ${r.months.length} 个月。${r.months.some(x=>x.stale)?'部分报表已过时，请先修订。':'未封存月份不计入年度总计。'}</p><div class="metrics">${metric('全年已确认收入',money(r.income),'已封存月份汇总')}${metric('全年实际支出',money(r.expense),'普通消费与特殊费用')}${metric('全年财政结余',money(r.surplus),'理财损益单列')}${metric('全年投资损益',money(r.investmentGain),'产品损益之和')}</div><div class="two-col"><section class="panel"><h2>经济独立程度</h2>${[['自筹劳动收入',money(r.labor)],['自筹收入占普通收入',r.laborShare==null?'—':(r.laborShare*100).toFixed(1)+'%'],['自筹收入对支出覆盖率',r.laborCoverage==null?'—':(r.laborCoverage*100).toFixed(1)+'%'],['储蓄动用次数',r.savingsUseCount+'次'],['储蓄动用金额',money(r.savingsUseAmount)]].map(([l,v])=>`<div class="key-value"><span>${l}</span><strong>${v}</strong></div>`).join('')}<p class="footnote">收入占比和覆盖率使用已封存月份的相同统计范围；本金借还和内部调拨不算收入。</p></section><section class="panel"><h2>资产积累</h2><div class="key-value"><span>所覆盖期间净资产变化</span><strong>${money(r.netChange)}</strong></div><div class="key-value"><span>所覆盖期间储蓄变化</span><strong>${money(r.savingsChange)}</strong></div><p class="footnote">${r.months.length?'覆盖 '+r.months[0].month+' 至 '+r.months.at(-1).month:'封存月报后开始汇总。'}。月份不连续时，期间资产变化可能包含未封存月份，不能视为年度完整结论。</p></section></div><section class="panel table-wrap"><div class="panel-head"><h2>各月财政比较</h2></div><table><thead><tr><th>月份</th><th class="right">收入</th><th class="right">实际支出</th><th class="right">财政结余</th><th class="right">投资损益</th></tr></thead><tbody>${r.months.map(m=>`<tr><td>${m.month}${m.stale?' · 待修订':''}</td><td class="right number">${money(m.income)}</td><td class="right number">${money(m.consumption+m.special)}</td><td class="right number">${money(m.surplus)}</td><td class="right number">${money(m.investmentGain)}</td></tr>`).join('')}</tbody></table></section>`;}
function historyView(){const monthly=latestReports(),rs=trendPeriod==='month'?monthly:[...new Set(monthly.map(x=>x.month.slice(0,4)))].sort().map(y=>{const a=annualReport(state,y);return {month:y,report:{closing:{net:a.months.at(-1).closing.net},surplus:a.surplus}};}),p=policyAt(state,now()),t=totals(state);return `<div class="tabs"><button class="${trendPeriod==='month'?'active':''}" data-action="trend-period" data-value="month">月度趋势</button><button class="${trendPeriod==='year'?'active':''}" data-action="trend-period" data-value="year">年度趋势</button></div>`+ `<div class="two-col"><section class="panel"><div class="panel-head"><h2>净资产趋势</h2><span class="badge">${trendPeriod==='year'?'年度最后封存值':'月末封存值'}</span></div>${simpleChart(rs)}</section><section class="panel"><div class="panel-head"><h2>普通财政结余</h2><span class="badge">投资损益独立</span></div>${simpleChart(rs,'surplus')}</section></div><section class="panel"><div class="panel-head"><h2>月报版本与修订</h2></div>${state.settlements.length?`<div class="table-wrap"><table><thead><tr><th>月份 / 版本</th><th>封存时间</th><th>说明</th><th class="right">净资产</th><th></th></tr></thead><tbody>${[...state.settlements].reverse().map(x=>`<tr><td>${x.month} · v${x.version}<span class="table-sub">${x.stale?'受后续更正影响':'封存记录'}</span></td><td>${date(x.closedAt)}</td><td>${esc(x.reason)}</td><td class="right number">${money(x.report.closing.net)}</td><td><button class="btn small" data-action="frozen-report" data-id="${x.id}">查看</button></td></tr>`).join('')}</tbody></table></div>`:empty('历史记录尚未开始','月结后会保留正式报表；纠错会生成新版本。')}</section><h2 class="section-title">储蓄恢复测算</h2><section class="panel"><p class="policy-note">当前储蓄缺口 ${money(Math.max(0,p.reserve-t.savings))}。填写一个假设的每月净增加额，估算恢复所需月份。</p><form data-form="forecast"><div class="form-grid">${field('假设每月净增加额（元）','amount','number','300','假设不发生额外损失，按每月稳定净增加额测算。',true)}<div class="field"><span>预计恢复</span><p id="forecast-result" class="reserve-number">—</p></div></div><div class="form-error"></div><button class="btn" type="submit">计算所需月份</button></form><p class="footnote">预测不是实际资金，不会改变任何账户余额。</p></section>`;}
const policyLabels={reserve:'储蓄基准',retained:'月末流动最低留存',low:'流动余额预警线',freeLow:'自由调配资金提示线',temporaryMin:'家庭临时补充下限',temporaryMax:'家庭临时补充上限',laborSavingsBps:'劳动收入储蓄比例',sweepBps:'月末超额流动转储蓄比例',otherSavingsBps:'其他收入储蓄比例'};
