function restoreForm(){showModal('校验备份 / 恢复账本',formWrap('restore',`<div class="notice">先校验备份。为保护历史，只允许恢复到尚未建账的空账本；已有账本仍可校验文件。</div><label class="field">JSON备份文件<input name="file" type="file" accept=".json,application/json" required></label><div id="restore-preview"></div><div class="checks"><label><input name="restore" type="checkbox" ${state.setup?'disabled':''}>校验通过后恢复到当前空账本</label></div>${field('恢复时输入当前登录密码','password','password','','只校验时不需要密码')}`,'校验 / 恢复'));}
function frozenView(id){const f=state.settlements.find(x=>x.id===id),r=f.report;showModal(`${f.month} · 封存 v${f.version}`,`<div class="notice"><span>${date(f.closedAt)}封存 · ${esc(f.reason)}${f.stale?'<br>后续账目变动已影响本期，旧版本内容保持不变。':''}</span></div>${[['普通收入',r.income],['普通消费',r.consumption],['特殊费用',r.special],['财政结余',r.surplus],['投资损益',r.investmentGain],['期末流动资金',r.closing.liquid],['期末储蓄资产',r.closing.savings],['期末债权',r.closing.receivables],['期末债务',r.closing.liabilities],['期末净资产',r.closing.net],['月末应调拨',r.expectedSweep],['月末实际调拨',r.actualSweep]].map(([l,v])=>`<div class="key-value"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}<p class="footnote">政策版本 ${esc(r.policyId)}<br>账本来源 r${f.sourceRevision} · ${r.incomplete?'不完整统计期间':'自然月统计'}</p><div class="form-buttons">${btn('关闭','modal-close')}</div>`);}
async function action(el){const a=el.dataset.action,id=el.dataset.id;
if(a==='modal-close'){modal.close();return;}if(a==='reload'){await boot();toast('账本已刷新');return;}
if(a==='account-add')return accountForm();if(a==='account-edit')return accountForm(id);if(a==='account-kind-correct')return cashCorrectionForm(id);if(a==='balances')return balanceForm();if(a==='month-balances')return balanceForm(true);if(a==='opening-balances')return balanceForm(true,true);
if(a==='tx')return txForm();if(a==='investment-tx')return txForm('invest');if(a==='tx-edit'){const t=state.transactions.find(t=>t.id===id);return txForm(t.kind,t);}if(a==='obligation-add')return obligationForm();if(a==='obligation-edit'){const o=state.obligations.find(x=>x.id===id);return showModal('更正借还款档案',formWrap('obligation-edit',`<input type="hidden" name="id" value="${o.id}">${field('对方姓名 / 名称','party','text',o.party,'',true)}${field('期初未结清本金（元）','opening','number',num(o.opening),'建账后新增的本金请更正原借还款事项；此处仅修正期初本金。',true)}${field('档案说明','memo','text',o.memo)}${field('更正理由','reason','text','','保留更正前内容，受影响月报需修订。',true)}`));}
if(a==='account-filter'){accountFilter=el.dataset.value;render();return;}if(a==='tx-filter'){txFilter=el.dataset.value;render();return;}if(a==='report-tab'){tab=el.dataset.value;render();return;}
if(a==='trend-period'){trendPeriod=el.dataset.value;render();return;}if(a==='policy-add')return policyForm();if(a.startsWith('export-'))return exportForm(a.slice(7));if(a==='restore')return restoreForm();
if(a==='platform-ref')return showModal('平台总资产参考值',formWrap('platform-ref',`${select('平台','platform',[...new Set(state.accounts.map(a=>a.platform))].map(p=>[p,p]))}${field('平台显示的总资产（元）','amount','number','','仅作核对，不加入资产总额。',true)}${field('参考值实际时点（北京时间）','asOf','datetime-local',localNow(),'',true)}`));
if(a==='logout'){await api('/logout',{method:'POST',body:{}});modal.close();state=null;csrf=null;return boot();}
if(a==='password')return showModal('修改登录密码',formWrap('password',`${field('当前密码','currentPassword','password','','',true)}${field('新密码','password','password','','12至128位；修改后全部会话退出。',true)}${field('再次输入新密码','confirmPassword','password','','',true)}`,'修改并退出登录'));
if(a==='sweep'){txForm('transfer');modal.querySelector('[name=purpose]').value='month_end';modal.querySelector('[name=purpose]').dispatchEvent(new Event('change',{bubbles:true}));const r=getReport();modal.querySelector('[name=amount]').value=num(r.sweepRemaining);modal.querySelector('[name=memo]').value=month+'月末结转';return;}
if(a==='close-month'){
 if(!['incomes','savings','loans','investments','consumption'].every(k=>document.querySelector(`[name=close-${k}]`)?.checked)){toast('请逐项确认月末核对清单');return;}
 const prior=state.settlements.some(x=>x.month===month);return showModal('确认正式月结',formWrap('close-month',`<input type="hidden" name="month" value="${month}"><div class="notice">将确认本期普通消费 ${money(getReport().consumption)}，并封存${month}财政报告。之后更正会保留原版并生成修订版本。</div>${prior?field('报表修订理由','reason','text','','说明本次修订内容',true):''}`,'确认并封存'));
}
if(a==='frozen-report')return frozenView(id);
if(a==='audit'){const r=await api('/audit');return showModal('审计记录',`<p class="footnote">记录操作版本、时间及内容哈希，历史操作不能被无痕改写。${r.importedCount?`另有${r.importedCount}条恢复前审计记录，包含于完整JSON备份。`:''}</p><div class="table-wrap"><table><thead><tr><th>版本</th><th>操作</th><th>记录时间</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>r${x.revision}</td><td>${esc(x.action)}</td><td>${esc(x.recorded_at.slice(0,19).replace('T',' '))}</td></tr>`).join('')}</tbody></table></div><p class="footnote">显示最近100条；完整历史包含于JSON备份。</p>`);}
}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled||busy)return;try{await action(target);}catch(err){toast(err.message);}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';render();window.scrollTo({top:0});});
document.addEventListener('change',e=>{const t=e.target;
if(t.id==='month-picker'){month=t.value;render();}if(t.id==='year-picker'&&/^\d{4}$/.test(t.value)){year=t.value;render();}
const form=t.closest('form[data-form]');
if(form&&['tx','tx-edit'].includes(form.dataset.form)){
 if(t.name==='kind'){
  const data=Object.fromEntries(new FormData(form)),previousSlots=[...form.querySelectorAll('[data-account-slot]')].map(x=>x.dataset.accountSlot);
  $('#tx-fields').innerHTML=txFields(t.value,data);
  updateTxAccounts(form,{data,previousSlots});
 }
 if(t.name==='at')updateTxAccounts(form);
 if(t.name==='fromId'&&form.elements.toId)updateTxAccounts(form,{changedSlot:'fromId'});
 if(t.name==='void')updateTxSubmit(form);
}
if(t.name==='kind'&&t.closest('form')?.dataset.form==='account-add'&&t.value==='investment'){t.form.elements.group.value='savings';t.form.elements.restriction.value='redeem';}
if(t.name==='purpose'){$('#transfer-related').innerHTML=t.value==='income_allocation'?select('关联收入','relatedId',state.transactions.filter(x=>x.kind==='income'&&!x.void).map(x=>[x.id,date(x.at)+' '+x.memo+' '+money(x.amount)])):t.value==='investment_allocation'?select('关联现金分红','relatedId',state.transactions.filter(x=>x.kind==='dividend'&&!x.void).map(x=>[x.id,date(x.at)+' '+x.memo+' '+money(x.amount)])):t.value==='month_end'?field('对应月份','relatedId','month',month,'请在同一自然月内完成实际调拨',true):'';updateTxAccounts(form);}
});
document.addEventListener('submit',async e=>{
 const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();if(busy)return;busy=true;const button=form.querySelector('[type=submit]');button.disabled=true;const error=form.querySelector('.form-error');if(error)error.textContent='';const p=Object.fromEntries(new FormData(form)),type=form.dataset.form;
 try{
 if(type==='auth'){if(!authState.configured&&p.password!==p.confirmPassword)throw new Error('两次密码输入不一致');const r=await api(authState.configured?'/login':'/register',{method:'POST',body:p});csrf=r.csrf;await boot();return;}
 if(type==='initialize'){await command('initialize',{at:stamp(p.at)});toast('建账起点已保存，请添加实际账户');return;}
 if(type==='account-add'){await command('account.add',{...p,amount:cents(p.amount),at:p.openingMode==='initial'?state.setup.at:now()});modal.close();toast('账户已建立');return;}
 if(type==='account-edit'){await command('account.update',{...p,at:stamp(p.at)});modal.close();toast('账户变更已保存');return;}
 if(type==='account-kind-correct'){await command('account.kind.correct',{...p,confirmed:!!p.confirmed});modal.close();toast('资产性质已更正，审计记录已保留');return;}
 if(type==='balances'||type==='month-balances'){const asOf=stamp(p.asOf);const items=state.accounts.filter(a=>p['checked-'+a.id]).map(a=>({accountId:a.id,asOf,amount:cents(p['amount-'+a.id])}));if(!items.length)throw new Error('请勾选实际核验的账户');await command('balance.confirm',{items});modal.close();toast('余额与核验时间已保存');return;}
 if(type==='obligation-add'){await command('obligation.add',{...p,opening:cents(p.opening),at:p.openingMode==='initial'?state.setup.at:now()});modal.close();toast('档案已建立，新增本金请登记借出或借入事项');return;}
 if(type==='obligation-edit'){await command('obligation.update',{...p,opening:cents(p.opening)});modal.close();toast('档案更正已保存，原内容已保留');return;}
 if(type==='tx'||type==='tx-edit'){
  const prior=state.transactions.find(t=>t.id===p.id);
  const tx=p.void&&prior?{...prior,reason:p.reason,void:true}:{...p,at:stamp(p.at),amount:cents(p.amount),direction:Number(p.direction||1),void:false};
  if(!tx.void){
   validateTransactionTime(state,tx.at);
   for(const slot of transactionAccountSlots(tx.kind)){
    const issue=transactionAccountIssue(state,tx,slot,tx[slot],prior);
    if(issue)throw new Error(issue);
   }
  }
  await command(type==='tx'?'transaction.add':'transaction.correct',tx);
  modal.close();toast(type==='tx'?'事项已入账':'更正已保存，旧记录已保留');return;
 }
 if(type==='policy-add'){const out={effective:p.effective};for(const k of Object.keys(policyLabels))out[k]=cents(p[k]);await command('policy.add',out);modal.close();toast('新政策版本已保存');return;}
 if(type==='platform-ref'){await command('platform.check',{platform:p.platform,amount:cents(p.amount),asOf:stamp(p.asOf)});modal.close();toast('参考值已保存，不参与资产加总');return;}
 if(type==='close-month'){await command('month.close',{month:p.month,reason:p.reason,confirmed:true});modal.close();toast('正式月报已封存');return;}
 if(type==='export'){const res=await api('/export',{method:'POST',body:{format:p.format,password:p.password},raw:true});const blob=await res.blob();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`personal-treasury-${now().slice(0,10)}.${p.format==='csv'?'csv':'json'}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);modal.close();toast('导出文件已生成');return;}
 if(type==='restore'){const file=form.querySelector('[name=file]').files[0];if(file.size>8*1024*1024)throw new Error('备份文件不能超过8MB');let b;try{b=JSON.parse(await file.text());}catch{throw new Error('不是有效的JSON文件');}const info=await api('/restore/verify',{method:'POST',body:{backup:b}});$('#restore-preview').innerHTML=`<div class="notice">校验通过：${info.accounts}个账户、${info.transactions}项记录、${info.settlements}份月报。净资产 ${money(info.totals.net)}。</div>`;if(p.restore){state=await api('/restore',{method:'POST',body:{backup:b,password:p.password,requestId:crypto.randomUUID(),confirmation:'恢复到空账本'}});modal.close();render();toast('备份已恢复');}else toast('备份完整性与数据结构校验通过');return;}
 if(type==='password'){if(p.password!==p.confirmPassword)throw new Error('两次新密码输入不一致');await api('/password',{method:'POST',body:p});modal.close();state=null;csrf=null;await boot();toast('密码已更新，全部会话已退出');return;}
 if(type==='forecast'){const add=cents(p.amount);if(add<=0)throw new Error('假设每月净增加额须大于零');const gap=Math.max(0,policyAt(state,now()).reserve-totals(state).savings);$('#forecast-result').textContent=gap===0?'已达到基准':Math.ceil(gap/add)+'个月';return;}
 }catch(err){if(error&&error.isConnected)error.textContent=err.message;else toast(err.message);if(state&&['tx','tx-edit'].includes(type))updateTxAccounts(form);}finally{busy=false;if(button.isConnected){if(['tx','tx-edit'].includes(type))updateTxSubmit(form);else button.disabled=false;}}
});
window.addEventListener('online',()=>toast('网络已恢复，可继续保存记录'));
window.addEventListener('offline',()=>toast('已离线，暂时无法保存。请联网后继续。'));
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
boot();
